declare(strict_types=1);session_name('googa');session_start();require_once __DIR__.'/lib/store.php';header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store, max-age=0');$context=googa_session_context();googa_require_owner($context);if(empty($_SESSION['googa_correction_csrf']))$_SESSION['googa_correction_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['googa_correction_csrf'];if($_SERVER['REQUEST_METHOD']!=='POST'||!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(400);echo json_encode(['ok'=>false]);exit;}$original=trim((string)($_POST['original']??''));$proposal=trim((string)($_POST['proposal']??''));if($original===''||$proposal===''||mb_strlen($original)>3000||mb_strlen($proposal)>3000){http_response_code(422);echo json_encode(['ok'=>false]);exit;}$data=googa_load_data();$data['corrections'][]=['id'=>bin2hex(random_bytes(8)),'status'=>'new','page'=>substr((string)($_POST['page']??''),0,240),'selector'=>substr((string)($_POST['selector']??''),0,500),'original'=>$original,'proposal'=>$proposal,'note'=>substr(trim((string)($_POST['note']??'')),0,1000),'owner'=>(string)$context['email'],'created_at'=>googa_now()];googa_save_data($data);echo json_encode(['ok'=>true]);
